package com.guocheng.mediapocket;
import java.util.*;import com.github.catvod.crawler.Spider;
public class TvSpiderRulesTest {
 static void check(boolean b,String why){if(!b)throw new AssertionError(why);}
 static class Fake extends Spider{String seen="";public String homeContent(boolean filter){seen="home:"+filter;return "home";}public String categoryContent(String id,String page,boolean filter,HashMap<String,String> ext){seen=id+":"+page+":"+filter;return "category";}public String searchContent(String word,boolean quick){return "";}public String searchContent(String word,boolean quick,String page){seen=word+":"+quick+":"+page;return "search";}public String detailContent(List<String> ids){seen=ids.get(0);return "detail";}public String playerContent(String flag,String id,List<String> vip){seen=flag+":"+id+":"+vip.get(0);return "player";}}
 static class DualSearch extends Spider {public String searchContent(String key,boolean quick){return "{\"list\":[{\"vod_id\":\"legacy\"}]}";}public String searchContent(String key,boolean quick,String page){return "{\"list\":[]}";}}
 static class MutatingDetail extends Spider {public String detailContent(List<String> ids){String original=ids.get(0);ids.set(0,"resolved:"+original);ids.add("temporary");ids.remove(1);return ids.get(0);}}
 public static void main(String[] args)throws Exception{byte[] bytes="fixture".getBytes("UTF-8");String md5=TvSpiderRules.digest(bytes,"MD5");TvSpiderRules.verify(bytes,md5);check(TvSpiderRules.md5("https://example.org/jar;md5;"+md5.toUpperCase(Locale.ROOT)).equals(md5),"case-normalized checksum");boolean blocked=false;try{TvSpiderRules.verify(bytes,"00000000000000000000000000000000");}catch(Exception e){blocked=true;}check(blocked,"checksum mismatch blocks load");check(TvSpiderRules.className("csp_LibvioGuard").equals("com.github.catvod.spider.LibvioGuard"),"CSP class mapping");blocked=false;try{TvSpiderRules.className("csp_../../Other");}catch(Exception e){blocked=true;}check(blocked,"invalid class input rejected");Fake f=new Fake();List<String> vip=Arrays.asList("VIP");check(TvSpiderDispatch.invoke(f,"home","","",1,vip).equals("home")&&f.seen.equals("home:true"),"home call");TvSpiderDispatch.invoke(f,"category","movies","",2,vip);check(f.seen.equals("movies:2:true"),"category args");TvSpiderDispatch.invoke(f,"search","test","",3,vip);check(f.seen.equals("test:false:3"),"paged search fallback");TvSpiderDispatch.invoke(f,"detail","video1","",1,vip);check(f.seen.equals("video1"),"detail IDs");TvSpiderDispatch.invoke(f,"player","token","route",1,vip);check(f.seen.equals("route:token:VIP"),"player args and VIP flags");check(TvSpiderDispatch.invoke(new MutatingDetail(),"detail","video1","",1,vip).equals("resolved:video1"),"detail plugin may replace/add/remove IDs without UnsupportedOperationException");check(TvSpiderDispatch.invoke(new DualSearch(),"search","test","",1,vip).contains("legacy"),"empty paged response falls back to implemented legacy search");System.out.println("PASS: mutable detail ID regression; component checksums, CSP class mapping, all five operation arguments and paged search fallback");}
}
